function norm(s){return (s||'').toLowerCase()}
function haystack(k){const a=BK.en[k],b=BK.mr[k];return norm([a.title,a.cat,a.desc,a.tag,b.title,b.cat,b.desc,b.tag].join(' '))}
function ordered(){const own=LANG;return KEYS.slice().sort((a,b)=>(ORIG[a]===own?0:1)-(ORIG[b]===own?0:1)||(AV.includes(a)?0:1)-(AV.includes(b)?0:1))}
function visible(){const q=norm(QUERY).trim();return ordered().filter(k=>(FILTER==='all'||ORIG[k]===FILTER)&&(!KONLY||AV.includes(k))&&(!q||haystack(k).includes(q)))}
/* rendering */
function chipsHtml(){const c=(id,l,p)=>`<button class="chip" type="button" data-f="${id}" aria-pressed="${p}">${l}</button>`;return c('all',T('fAll'),FILTER==='all')+c('en',T('fEn'),FILTER==='en')+c('mr',T('fMr'),FILTER==='mr')+`<button class="chip" type="button" data-k="1" aria-pressed="${KONLY}">${T('fKindle')}</button><a class="chip" href="${POTHI[LANG]}" target="_blank" rel="noopener">${T('fPothi')}</a>`}
function renderBooks(animate){const list=visible(),sh=$('shelf');$('chips').innerHTML=chipsHtml();$('count').textContent=T('cnt')(list.length,KEYS.length);
if(!list.length){sh.innerHTML=`<p class="empty" style="grid-column:1/-1">${T('none')}</p>`;return}
sh.innerHTML=list.map((k,i)=>{const b=BK[LANG][k],av=AV.includes(k);return `<button class="bcard" type="button" data-open="${k}" style="--i:${animate?i:0}" aria-label="${b.title} — ${av?T('avL'):T('soL')}"><span class="bcover"><img src="assets/${k}.webp" alt="" width="640" height="960" loading="lazy" decoding="async"><span class="tag"><i>${ORIG[k]==='en'?T('lEn'):T('lMr')}</i></span><img class="st" src="assets/st-${av?'kindle':'soon'}-${LANG}.webp" alt="${av?T('avL'):T('soL')}" width="420" height="250" decoding="async"></span><span class="bt">${b.title}</span><span class="bc">${b.cat}</span></button>`}).join('');
sh.querySelectorAll('img').forEach(im=>{const f=()=>im.classList.add('ld');if(im.complete)f();else im.addEventListener('load',f,{once:true});im.addEventListener('error',f,{once:true})})}
function renderCover(){const ha=$('heroArt'),am=ha.querySelector('.amb');ha.innerHTML=`<button class="bk" type="button" data-go="books" aria-label="${T('coverTitle')} — ${T('coverOpen')}"><span class="bk-pages" aria-hidden="true"></span><span class="bk-board"><span class="bk-spine" aria-hidden="true"></span><span class="bk-face"><span class="bk-frame" aria-hidden="true"><i class="tl"></i><i class="tr"></i><i class="bl"></i><i class="br"></i></span><span class="bk-kicker">${T('coverKick')}</span><img class="bk-logo" src="assets/lekhani-logo-circle.webp" width="600" height="600" alt=""><span class="bk-title">${T('coverTitle')}</span><span class="bk-rule" aria-hidden="true"><i></i></span><span class="bk-sub">${T('coverSub')}</span><span class="bk-author">${T('coverAuthor')}</span><span class="bk-count">${T('coverCount')}</span><span class="bk-open">${T('coverOpen')} →</span></span></span><span class="bk-ribbon" aria-hidden="true"></span></button>`;if(am)ha.insertBefore(am,ha.firstChild)}
function renderSheet(){if(!OPEN)return;const k=OPEN,b=BK[LANG][k],av=AV.includes(k),mr=LANG==='mr';
$('shImg').src='assets/'+k+'.webp';const st=$('shSt');st.alt='';st.src='assets/st-'+(av?'kindle':'soon')+'-'+LANG+'.webp';st.style.animation='none';void st.offsetWidth;st.style.animation='';$('shImg').alt=b.title+' — '+T('cover');
$('shCat').textContent=b.cat+' · '+(ORIG[k]==='en'?T('edEn'):T('edMr'))+' · '+(av?T('avL'):T('soL'));
$('shTitle').textContent=b.title;const g=$('shTag');g.textContent=b.tag||'';g.hidden=!b.tag;
const tx=$('shText');tx.innerHTML=b.body;tx.lang=LANG;
const by=$('shBuy');by.hidden=!av;if(av){by.href=KINDLE[ORIG[k]];by.textContent=T('buy')}const pr=$('shPrint');pr.href=POTHI[ORIG[k]];pr.textContent=T('print');
$('shAsk').textContent=T('ask')}
function openBook(k){OPEN=k;renderSheet();const d=$('sheet');$('shBody').scrollTop=0;if(d.showModal){if(!d.open)d.showModal()}else d.setAttribute('open','');save('lekhani-book',k)}
function closeBook(){OPEN=null;const d=$('sheet');if(d.close)d.close();else d.removeAttribute('open')}
/* i18n */
function renderEssay(){const h=$('essH'),b=$('essay');if(!h||!b)return;const L=LANG,d=ESSAY,n=d[L].length,pull={5:1,16:1,n1:1};
h.textContent=d.t[L];b.lang=L;
b.innerHTML=d[L].map((p,i)=>`<p class="${i===0?'lead':(i===5||i===16)?'pull':i===n-1?'close':''}">${p.replace(/&/g,'&amp;').replace(/</g,'&lt;')}</p>`).join('')+`<div class="e-sig"><b>${d.sig[L][0]}</b><span>${d.sig[L][1]}</span><i>${d.sig[L][2]}</i></div>`}
function applyText(){renderEssay();renderSecs();renderNote();const R=document.documentElement;R.lang=LANG;document.title=T('title');
document.querySelectorAll('[data-t]').forEach(e=>{e.innerHTML=T(e.dataset.t)});
document.querySelectorAll('[data-aria]').forEach(e=>e.setAttribute('aria-label',T(e.dataset.aria)));
const q=$('q');q.placeholder=T('searchPh');
document.querySelectorAll('.lang').forEach(g=>{g.dataset.active=LANG;g.querySelectorAll('.lang-opt').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===LANG)))});
$('portrait').alt=T('portraitAlt');$('cKindle').href=KINDLE[LANG];$('bKindle').href=KINDLE[LANG];$('bPothi').href=POTHI[LANG];$('bKst').src='assets/st-kindle-'+LANG+'.webp';$('cPothi').href=POTHI[LANG];$('year').textContent=new Date().getFullYear();$('copyLbl').textContent=T('cCopy');
renderCover();renderBooks(false);renderSheet();
document.querySelectorAll('.acc-h').forEach(b=>b.setAttribute('aria-expanded',String(b.parentNode.classList.contains('open'))))}
function setLang(l,first){if(!UI[l]||(l===LANG&&booted&&!first))return;const st=$('stage');
const go=()=>{LANG=l;applyText();save('lekhani-lang',l);syncHash()};
if(reduce||first||!booted){go();return}
st.classList.add('swap');setTimeout(()=>{go();requestAnimationFrame(()=>st.classList.remove('swap'))},130)}
function syncHash(){try{history.replaceState(null,'','#'+LANG+(TAB==='home'?'':'/'+TAB))}catch(e){}}
/* tabs */
function setTab(t,focus){if(!['home','books','buy','about','contact'].includes(t))t='home';TAB=t;
document.querySelectorAll('.tab').forEach(b=>{const on=b.dataset.tab===t;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});
document.querySelectorAll('.panel').forEach(p=>{const on=p.id==='p-'+t;p.classList.toggle('active',on);p.inert=!on;if(on)p.scrollTop=0});
try{sessionStorage.setItem('lekhani-tab',t)}catch(e){}syncHash();if(focus)$('t-'+t).focus()}
document.addEventListener('click',e=>{
const g=e.target.closest('[data-go]');if(g){setTab(g.dataset.go);return}
const tb=e.target.closest('.tab');if(tb){setTab(tb.dataset.tab);return}
const lo=e.target.closest('.lang-opt');if(lo){setLang(lo.dataset.lang);return}
const o=e.target.closest('[data-open]');if(o){openBook(o.dataset.open);return}
const f=e.target.closest('[data-f]');if(f){FILTER=f.dataset.f;renderBooks(true);return}
const kk=e.target.closest('[data-k]');if(kk){KONLY=!KONLY;renderBooks(true);return}
const ah=e.target.closest('.acc-h');if(ah){const it=ah.parentNode,was=it.classList.contains('open');document.querySelectorAll('.acc-i').forEach(x=>{x.classList.remove('open');x.querySelector('.acc-h').setAttribute('aria-expanded','false')});if(!was){it.classList.add('open');ah.setAttribute('aria-expanded','true')}}});
$('tabs').addEventListener('keydown',e=>{const order=['home','books','buy','about','contact'],N=order.length;let i=order.indexOf(TAB);if(e.key==='ArrowRight')i=(i+1)%N;else if(e.key==='ArrowLeft')i=(i+N-1)%N;else return;e.preventDefault();setTab(order[i],true)});
$('q').addEventListener('input',e=>{QUERY=e.target.value;$('searchBox').classList.toggle('has',!!QUERY);renderBooks(false)});
$('qClr').addEventListener('click',()=>{QUERY='';$('q').value='';$('searchBox').classList.remove('has');renderBooks(false);$('q').focus()});
$('shX').addEventListener('click',closeBook);$('shAsk').addEventListener('click',()=>{closeBook();setTab('contact')});
$('sheet').addEventListener('click',e=>{if(e.target===$('sheet'))closeBook()});$('sheet').addEventListener('close',()=>{OPEN=null});
$('copyMail').addEventListener('click',async()=>{const l=$('copyLbl');try{await navigator.clipboard.writeText('bhave.paddy@gmail.com');l.textContent=T('copied')}catch(e){const r=document.createRange();r.selectNodeContents($('mailAddr'));const s=getSelection();s.removeAllRanges();s.addRange(r);l.textContent=T('press')}setTimeout(()=>l.textContent=T('cCopy'),2200)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&OPEN)closeBook()});
/* boot */
(function(){const m=(location.hash||'').toLowerCase().match(/^#(en|mr)(?:\/(home|books|buy|about|contact))?$/);
const sv=load('lekhani-lang');window.__preLang=m?m[1]:(sv==='en'||sv==='mr'?sv:'');let l=m?m[1]:(sv==='mr'?'mr':'en');let t=m&&m[2]?m[2]:'home';
if(!m){try{t=sessionStorage.getItem('lekhani-tab')||'home'}catch(e){}}
LANG=l;FILTER=l;setLang(l,true);booted=true;setTab(t);
window.applyLang=function(x){FILTER=x;LANG=x;applyText();save('lekhani-lang',x);syncHash()}})();
